class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        total = n + m - 1
        word = ['a'] * total
        fixed = [False] * total

        for i in range(n):
            if str1[i] == 'T':
                for j in range(m):
                    pos = i + j
                    if fixed[pos] and word[pos] != str2[j]:
                        return ""
                    word[pos] = str2[j]
                    fixed[pos] = True

        for i in range(n):
            if str1[i] == 'F':
                matches = all(word[i + j] == str2[j] for j in range(m))
                if matches:
                    changed = False
                    for j in range(m - 1, -1, -1):
                        pos = i + j
                        if not fixed[pos]:
                            word[pos] = 'b' if str2[j] == 'a' else 'a'
                            changed = True
